        raxIterator ri;
        raxStart(&ri, Users);
        raxSeek(&ri, "^", NULL, 0);
        while (raxNext(&ri)) {
            user *u = ri.data;
            if (justnames) {
                addReplyBulkCBuffer(c, u->name, sdslen(u->name));
            } else {
                /* Return information in the configuration file format. */
